import React, { useState } from 'react';
import { motion } from 'framer-motion';
import DashboardLayout from '../components/dashboard/DashboardLayout';

// MUI Icons
import SmartToyIcon from '@mui/icons-material/SmartToy';
import PsychologyIcon from '@mui/icons-material/Psychology';
import SchoolIcon from '@mui/icons-material/School';
import AssignmentTurnedInIcon from '@mui/icons-material/AssignmentTurnedIn';
import MeetingRoomIcon from '@mui/icons-material/MeetingRoom';
import SupervisedUserCircleIcon from '@mui/icons-material/SupervisedUserCircle';
import AlarmIcon from '@mui/icons-material/Alarm';
import LanguageIcon from '@mui/icons-material/Language';
import InfoIcon from '@mui/icons-material/Info';

const AgentsPage = () => {
  // AI Agents data
  const [agents, setAgents] = useState([
    {
      id: 'meeting-agent',
      name: 'Meeting Agent',
      description: 'Specialized agent for handling meeting requests and scheduling.',
      icon: <MeetingRoomIcon />,
      enabled: true,
      active: true,
      status: 'active',
      canToggle: true,
    },
    // Coming soon agents
    {
      id: 'calendar-agent',
      name: 'Calendar Agent',
      description: 'Manages calendar integration for scheduling and availability checks.',
      icon: <AlarmIcon />,
      enabled: false,
      active: false,
      status: 'coming_soon',
    },
    {
      id: 'general-support',
      name: 'General Support Agent',
      description: 'Stores basic information for topics and answers questions based on it.',
      icon: <SupervisedUserCircleIcon />,
      enabled: false,
      active: false,
      status: 'coming_soon',
    },
    {
      id: 'custom-agent',
      name: 'Customized Agent',
      description: 'Adapts to specific needs and workflow requirements for your organization.',
      icon: <LanguageIcon />,
      enabled: false,
      active: false,
      status: 'coming_soon',
    },
  ]);

  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState(null);

  const handleAgentToggle = async (agentId) => {
    // Don't allow toggling for coming soon agents or agents that can't be toggled
    const agentIndex = agents.findIndex(agent => agent.id === agentId);
    if (agents[agentIndex].status === 'coming_soon' || !agents[agentIndex].canToggle) {
      return;
    }

    setLoading(true);
    setError(null);
    setSuccess(false);

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 800));

      // Update agent state
      const updatedAgents = [...agents];
      updatedAgents[agentIndex].enabled = !updatedAgents[agentIndex].enabled;
      setAgents(updatedAgents);

      setSuccess(true);
      setLoading(false);

      // Clear success message after 3 seconds
      setTimeout(() => setSuccess(false), 3000);
    } catch (err) {
      console.error('Error toggling agent:', err);
      setError('Failed to update agent status. Please try again.');
      setLoading(false);
    }
  };

  return (
    <DashboardLayout>
      <div style={{ maxWidth: '1000px', margin: '0 auto' }}>
        <header style={{ marginBottom: '24px' }}>
          <h1 style={{ 
            fontSize: '24px', 
            fontWeight: '700', 
            color: 'var(--text-color)',
            marginBottom: '8px'
          }}>
            AI Agents
          </h1>
          <p style={{ fontSize: '15px', color: 'var(--body-color)' }}>
            Manage the AI agents that process and respond to your emails
          </p>
        </header>

        {success && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
            style={{
              backgroundColor: 'rgba(16, 185, 129, 0.1)',
              borderRadius: '6px',
              padding: '12px 16px',
              marginBottom: '24px',
              color: '#10B981',
              fontSize: '14px',
            }}
          >
            Agent status updated successfully!
          </motion.div>
        )}

        {error && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
            style={{
              backgroundColor: 'rgba(239, 68, 68, 0.1)',
              borderRadius: '6px',
              padding: '12px 16px',
              marginBottom: '24px',
              color: '#EF4444',
              fontSize: '14px',
            }}
          >
            {error}
          </motion.div>
        )}

        {/* Active Agents Section */}
        <section style={{ marginBottom: '40px' }}>
          <h2 style={{
            fontSize: '18px',
            fontWeight: '600',
            color: 'var(--text-color)',
            marginBottom: '16px',
          }}>
            Active Agents
          </h2>

          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
            gap: '20px',
          }}>
            {agents
              .filter(agent => agent.status === 'active')
              .map((agent, index) => (
                <motion.div
                  key={agent.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.4, delay: index * 0.1 }}
                  style={{
                    backgroundColor: 'white',
                    borderRadius: '10px',
                    padding: '24px',
                    boxShadow: '0 2px 10px rgba(0, 0, 0, 0.05)',
                    position: 'relative',
                  }}
                >
                  <div style={{
                    position: 'absolute',
                    top: '20px',
                    right: '20px',
                  }}>
                    <label className="switch" style={{ position: 'relative', display: 'inline-block', width: '50px', height: '24px' }}>
                      <input
                        type="checkbox"
                        checked={agent.enabled}
                        onChange={() => handleAgentToggle(agent.id)}
                        disabled={loading || agent.status === 'coming_soon' || !agent.canToggle}
                        style={{ opacity: 0, width: 0, height: 0 }}
                      />
                      <span style={{
                        position: 'absolute',
                        cursor: (agent.status === 'coming_soon' || !agent.canToggle) ? 'not-allowed' : 'pointer',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        backgroundColor: agent.enabled ? 'var(--primary-color)' : '#ccc',
                        borderRadius: '34px',
                        transition: '0.4s',
                      }}>
                        <div style={{
                          position: 'absolute',
                          height: '16px',
                          width: '16px',
                          left: '4px',
                          bottom: '4px',
                          backgroundColor: 'white',
                          borderRadius: '50%',
                          transition: '0.4s',
                          transform: agent.enabled ? 'translateX(26px)' : 'translateX(0)',
                        }} />
                      </span>
                    </label>
                  </div>

                  <div style={{
                    width: '48px',
                    height: '48px',
                    borderRadius: '10px',
                    backgroundColor: 'rgba(74, 108, 247, 0.1)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    marginBottom: '16px',
                  }}>
                    <div style={{ color: 'var(--primary-color)', fontSize: '28px' }}>
                      {agent.icon}
                    </div>
                  </div>

                  <h3 style={{
                    fontSize: '16px',
                    fontWeight: '600',
                    color: 'var(--text-color)',
                    marginBottom: '8px',
                  }}>
                    {agent.name}
                  </h3>

                  <p style={{
                    fontSize: '14px',
                    color: 'var(--body-color)',
                    lineHeight: '1.5',
                    marginBottom: '16px',
                  }}>
                    {agent.description}
                  </p>

                  <div style={{
                    fontSize: '13px',
                    color: agent.enabled ? '#10B981' : '#9CA3AF',
                    fontWeight: '500',
                  }}>
                    {agent.enabled ? 'Enabled' : 'Disabled'}
                  </div>
                </motion.div>
              ))}
          </div>
        </section>

        {/* Coming Soon Agents Section */}
        <section>
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            marginBottom: '16px',
            gap: '8px'
          }}>
            <h2 style={{
              fontSize: '18px',
              fontWeight: '600',
              color: 'var(--text-color)',
              margin: 0,
            }}>
              Coming Soon
            </h2>
            <span style={{
              backgroundColor: 'rgba(79, 70, 229, 0.1)',
              color: '#4F46E5',
              fontSize: '12px',
              fontWeight: '500',
              padding: '4px 8px',
              borderRadius: '6px',
            }}>
              In Development
            </span>
          </div>

          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
            gap: '20px',
          }}>
            {agents
              .filter(agent => agent.status === 'coming_soon')
              .map((agent, index) => (
                <motion.div
                  key={agent.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.4, delay: index * 0.1 }}
                  style={{
                    backgroundColor: 'white',
                    borderRadius: '10px',
                    padding: '24px',
                    boxShadow: '0 2px 10px rgba(0, 0, 0, 0.05)',
                    position: 'relative',
                    opacity: 0.7,
                  }}
                >
                  <div style={{
                    position: 'absolute',
                    top: '20px',
                    right: '20px',
                  }}>
                    <label className="switch" style={{ position: 'relative', display: 'inline-block', width: '50px', height: '24px' }}>
                      <input
                        type="checkbox"
                        checked={false}
                        disabled={true}
                        style={{ opacity: 0, width: 0, height: 0 }}
                      />
                      <span style={{
                        position: 'absolute',
                        cursor: 'not-allowed',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        backgroundColor: '#ccc',
                        borderRadius: '34px',
                        transition: '0.4s',
                      }}>
                        <div style={{
                          position: 'absolute',
                          height: '16px',
                          width: '16px',
                          left: '4px',
                          bottom: '4px',
                          backgroundColor: 'white',
                          borderRadius: '50%',
                          transition: '0.4s',
                        }} />
                      </span>
                    </label>
                  </div>

                  <div style={{
                    width: '48px',
                    height: '48px',
                    borderRadius: '10px',
                    backgroundColor: 'rgba(156, 163, 175, 0.1)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    marginBottom: '16px',
                  }}>
                    <div style={{ color: '#9CA3AF', fontSize: '28px' }}>
                      {agent.icon}
                    </div>
                  </div>

                  <h3 style={{
                    fontSize: '16px',
                    fontWeight: '600',
                    color: 'var(--text-color)',
                    marginBottom: '8px',
                  }}>
                    {agent.name}
                  </h3>

                  <p style={{
                    fontSize: '14px',
                    color: 'var(--body-color)',
                    lineHeight: '1.5',
                    marginBottom: '16px',
                  }}>
                    {agent.description}
                  </p>

                  <div style={{
                    fontSize: '13px',
                    color: '#9CA3AF',
                    fontWeight: '500',
                  }}>
                    Coming Soon
                  </div>
                </motion.div>
              ))}
          </div>
        </section>

        {/* Info Section */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4, delay: 0.4 }}
          style={{
            backgroundColor: 'rgba(74, 108, 247, 0.05)',
            borderRadius: '10px',
            padding: '20px',
            marginTop: '40px',
            display: 'flex',
            alignItems: 'flex-start',
            gap: '16px',
          }}
        >
          <div style={{ 
            color: 'var(--primary-color)', 
            display: 'flex', 
            marginTop: '2px' 
          }}>
            <InfoIcon />
          </div>
          <div>
            <h3 style={{
              fontSize: '16px',
              fontWeight: '600',
              color: 'var(--text-color)',
              marginBottom: '8px',
            }}>
              About AI Agents
            </h3>
            <p style={{
              fontSize: '14px',
              color: 'var(--body-color)',
              lineHeight: '1.6',
              margin: 0,
            }}>
              AI Agents help automate your email workflow by handling specific tasks. Currently, you can enable or disable 
              the Meeting Agent which manages meeting-related emails. More specialized agents are under development 
              and will be available soon to further enhance your email management experience.
            </p>
          </div>
        </motion.div>
      </div>
    </DashboardLayout>
  );
};

export default AgentsPage;
